pub fn draw_sparkline<B: Backend>(terminal: &mut Terminal<B>) -> io::Result<()> {
    let rate = Duration::from_millis(200);
    let mut last_trick = Instant::now();
    loop {
        terminal.draw(sparkline)?;
        let timeout = last_trick
            .elapsed()
            .checked_sub(rate)
            .unwrap_or_else(|| Duration::from_millis(0));
        if event::poll(timeout)? {
            if let CEvent::Key(key) = event::read()? {
                if let KeyCode::Char('q') = key.code {
                    return Ok(());
                }
            }
        }
        if last_trick.elapsed() > rate {
            last_trick = Instant::now();
        }
    }
}

